import{_ as s,o as t,a as e,b as n}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"特殊寄存器","link":"/api/SIMD-API/tensor_api/special_register/special_register"},{"text":"set_saturation_flag","link":"/api/SIMD-API/tensor_api/special_register/set_saturation_flag"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/special_register/set_saturation_flag.md","filePath":"api/SIMD-API/tensor_api/special_register/set_saturation_flag.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1794877794000}'),l={name:"api/SIMD-API/tensor_api/special_register/set_saturation_flag.md"};function d(o,a,p,c,i,r){return t(),e("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>set_saturation_flag</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>按饱和模式类型设置对应饱和开关。<code>enable_sat</code>表示API语义上的“是否开启饱和”，接口内部会按模式处理不同语义。</p><p>各模式下<code>enable_sat</code>的含义如下：</p><p><strong>表1</strong> 饱和模式与enable_sat语义</p><table><thead><tr><th>saturation_mode</th><th>enable_sat=true</th><th>enable_sat=false</th><th>说明</th></tr></thead><tbody><tr><td>float_mode</td><td>饱和</td><td>非饱和</td><td>浮点计算及部分浮点精度转换场景的饱和控制，默认为非饱和状态。</td></tr><tr><td>float8_mode</td><td>饱和</td><td>非饱和</td><td>fp8相关场景的饱和控制，默认为饱和状态。</td></tr><tr><td>int_mode</td><td>饱和</td><td>截断</td><td>整数计算溢出时的饱和/截断控制，默认为非饱和状态。</td></tr><tr><td>cast_mode</td><td>饱和</td><td>截断</td><td>浮点转整数或整数转整数时的精度转换饱和控制，默认为饱和状态。仅在策略为<code>override_strategy::use_global</code>时生效。</td></tr></tbody></table><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_saturation_flag</span><span class="p">(</span><span class="n">saturation_mode</span><span class="w"> </span><span class="n">mode</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_sat</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mode</td><td>输入</td><td>饱和模式类型，类型为<code>saturation_mode</code>，取值见<strong>表1</strong>。</td></tr><tr><td>enable_sat</td><td>输入</td><td>是否开启饱和。<code>true</code>表示开启饱和，<code>false</code>表示关闭饱和（对<code>int_mode</code>为截断；对<code>float_mode</code>/<code>float8_mode</code>/<code>cast_mode</code>为非饱和或截断，见<strong>表1</strong>）。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><code>enable_sat</code>是API语义参数，同一布尔值在不同模式下的关闭语义不同（<code>int_mode</code>为截断，<code>float_mode</code>/<code>float8_mode</code>/<code>cast_mode</code>为非饱和或截断），请以<strong>表1</strong>为准。</li><li>当对<code>saturation_mode::float_mode</code>开启饱和模式前，需要通过<a href="set_saturation_strategy.html">set_saturation_strategy</a>开启全局饱和配置方可生效。</li><li>当<code>mode</code>为<code>saturation_mode::float8_mode</code>时，还需要先对<code>saturation_mode::float_mode</code>开启饱和模式才能生效。</li><li>当<code>mode</code>为<code>saturation_mode::cast_mode</code>时，还需将饱和策略设置为<code>override_strategy::use_global</code>，CAST才会生效。</li><li>本接口仅修改对应模式的饱和配置，不影响其他模式。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例调用<code>set_saturation_flag</code>接口。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_saturation_flag_kernel</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="n">set_saturation_strategy</span><span class="p">(</span><span class="n">override_strategy</span><span class="o">::</span><span class="n">use_global</span><span class="p">);</span>
<span class="w">    </span><span class="n">set_saturation_flag</span><span class="p">(</span><span class="n">saturation_mode</span><span class="o">::</span><span class="n">float_mode</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const u=s(l,[["render",d]]);export{h as __pageData,u as default};
